parameters.jsCode:
const items = $input.all();
return items.map(item => {
  const data = item.json.body || item.json;
  const destination = data.destination || 'Unknown';
  const tripName = data.tripName || `Trip to ${destination}`;
  const startDate = data.startDate || data.departureDate || '';
  const endDate = data.endDate || data.returnDate || '';

  // Flights
  const flights = data.flights || [];
  const flightDetails = flights.map(f =>
    `✈️ ${f.airline || ''} ${f.flightNumber || ''}: ${f.from || ''} → ${f.to || ''} | ${f.date || ''} ${f.time || ''}`
  ).join('\n');

  // Hotels
  const hotels = data.hotels || [];
  const hotelDetails = hotels.map(h =>
    `🏨 ${h.name || ''} | Check-in: ${h.checkIn || ''} | Check-out: ${h.checkOut || ''} | Conf: ${h.confirmation || ''}`
  ).join('\n');

  // Activities
  const activities = data.activities || [];
  const activityDetails = activities.map(a =>
    `📍 ${a.name || ''} — ${a.date || ''} ${a.time || ''} | ${a.notes || ''}`
  ).join('\n');

  const budget = data.budget || 'Not set';
  const travelers = data.travelers || [];

  return {
    json: {
      tripName,
      destination,
      startDate,
      endDate,
      flightDetails: flightDetails || 'No flights added',
      hotelDetails: hotelDetails || 'No hotels added',
      activityDetails: activityDetails || 'No activities planned',
      budget,
      travelers: Array.isArray(travelers) ? travelers.join(', ') : String(travelers),
      travelerEmails: data.travelerEmails || []
    }
  };
});

